Careful: attach handlers per drag with a named closure:

```js
function startDrag(e, li) {
  if (!e.isPrimary) return;
  const startEl = e.currentTarget;
  const id = e.pointerId;
  startEl.setPointerCapture(id);
  li.classList.add('is-dragging');
  let onMove, onUp;
  onMove = ev => {
    if (ev.pointerId !== id) return;
    const el = document.elementFromPoint(ev.clientX, ev.clientY);
    const target = el && el.closest('.disc-item');
    if (target && target !== li && li.closest('.disc-list') === target.closest('.disc-list')) {
      // remove previous is-over
      const prev = li.closest('.disc-list').querySelector('.disc-item.is-over');
      if (prev && prev !== li) prev.classList.remove('is-over');
      const rect = target.getBoundingClientRect();
      const before = ev.clientY < rect.top + rect.height / 2;
      li.closest('.disc-list').insertBefore(li, before ? target : target.nextSibling);
      if (target !== li) target.classList.add('is-over');
    }
  };
  onUp = ev => {
    startEl.removeEventListener('pointermove', onMove);
    startEl.removeEventListener('pointerup', onUp);
    li.closest('.disc-list').querySelectorAll('.disc-item.is-over').forEach(x => x.classList.remove('is-over'));
    li.classList.remove('is-dragging');
  };
  startEl.addEventListener('pointermove', onMove);
  startEl.addEventListener('pointerup', onUp);
  startEl.addEventListener('pointercancel', onUp);
}
```

