"use strict";
// Минимальный фейковый DOM: достаточно для полного запуска скрипта index.html.
const _registry = new Set();

class Element {
  constructor() {
    this._id = null;
    this._children = [];
    this._hidden = false;
    this._style = {};
    this._cls = new Set();
    this._dataset = {};
    this._props = {};
    this._text = "";
    this._listeners = {};
  }
  get id() { return this._id; }
  set id(v) { this._id = String(v); }
  get hidden() { return this._hidden; }
  set hidden(v) { this._hidden = !!v; }
  get style() { return this._style; }
  get classList() {
    const s = this._cls;
    return {
      add: (c) => s.add(String(c)),
      remove: (c) => s.delete(String(c)),
      toggle: (c, f) => (f ? s.add(String(c)) : s.delete(String(c))),
      contains: (c) => s.has(String(c)),
    };
  }
  get className() { return [...this._cls].join(" "); }
  set className(v) {
    this._cls.clear();
    for (const c of String(v).split(/\s+/)) if (c) this._cls.add(c);
  }
  get dataset() { return this._dataset; }
  setAttribute(name, value) {
    if (name.startsWith("data-")) this._dataset[name.slice(5)] = String(value);
    else this._props[name] = String(value);
  }
  getAttribute(name) { return this._props[name]; }
  focus() {}
  addEventListener(type, fn) { (this._listeners[type] || []).push(fn); }
  dispatch(type) {
    return (this._listeners[type] || []).map((fn) => fn({ target: this }));
  }
  get textContent() { return this._text + this._descendants().map((c) => c.textContent).join(""); }
  set textContent(v) { this._text = String(v); this._children.length = 0; }
  set innerHTML(v) { this._text = String(v); this._children.length = 0; }
  appendChild(c) { this._children.push(c); return c; }
  insertBefore(c, ref) {
    const i = this._children.indexOf(ref);
    if (i >= 0) this._children.splice(i, 0, c);
    else this._children.push(c);
    return c;
  }
  removeChild(c) {
    const i = this._children.indexOf(c);
    if (i >= 0) this._children.splice(i, 1);
    return c;
  }
  _descendants() {
    const out = [];
    for (const c of this._children) { out.push(c); out.push(...c._descendants()); }
    return out;
  }
}

class FakeDocument {
  constructor() {
    this._byId = new Map();
    this.documentElement = new Element();
    this.documentElement._id = "html";
  }
  addEl(id) {
    const e = new Element();
    if (id != null) e._id = String(id);
    this._byId.set(id, e);
    return e;
  }
  getElementById(id) { return this._byId.get(id) || null; }
  createElement(tag) { const e = new Element(); _registry.add(e); return e; }
  addEventListener(type, fn) { (this._listeners[type] || []).push(fn); }
  dispatch(type, data) {
    return (this._listeners[type] || []).map((fn) => fn(data));
  }
  querySelector() { return null; }
  querySelectorAll(sel) {
    const flat = [..._registry];
    if (sel === ".disc-pane") return flat.filter((n) => n._cls.has("disc-pane"));
    if (sel === ".disc-card") return flat.filter((n) => n._cls.has("disc-card"));
    if (sel === ".disc-list") return flat.filter((n) => n._cls.has("disc-list"));
    if (sel === ".disc-item") return flat.filter((n) => n._cls.has("disc-item"));
    const m = sel.match(/^\[([a-z-]+)]$/);
    if (m) return flat.filter((n) => m[1] in n._dataset);
    const eq = sel.match(/^\[([a-z-]+)=([^]\s]*)\]$/);
    if (eq) return flat.filter((n) => n._dataset[eq[1]] === eq[2]);
    return [];
  }
}

module.exports = { Element, FakeDocument };
