"use strict";
// Минимальный фейковый DOM: запуск скрипта index.html без браузера.
const _registry = new Set();

function matchSel(el, sel) {
  const parts = sel.trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return false;
  for (const p of parts) {
    if (p.startsWith(".")) { if (!el._cls.has(p.slice(1))) return false; }
    else if (p.startsWith("#")) { if (el._id !== p.slice(1)) return false; }
    else if (p.startsWith("[")) {
      const m = p.match(/^\[([a-z-]+)]$/);
      if (m && !(m[1] in el._dataset)) return false;
    }
    else if (p[0] === "/" || p.endsWith("]")) return false;
    else { if (el._tag && p !== el._tag) return false; }
  }
  return true;
}

class Element {
  constructor(tag) {
    this._id = null;
    this._tag = tag || null;
    this._children = [];
    this._parent = null;
    this._hidden = false;
    this._style = {};
    this._cls = new Set();
    this._dataset = {};
    this._props = {};
    this._text = "";
    this._listeners = {};
  }
  get id() { return this._id; }
  set id(v) { this._id = String(v); }
  get hidden() { return this._hidden; }
  set hidden(v) { this._hidden = !!v; }
  get style() { return this._style; }
  get classList() {
    const s = this._cls;
    return {
      add: (c) => s.add(String(c)),
      remove: (c) => s.delete(String(c)),
      toggle: (c, f) => (f ? s.add(String(c)) : s.delete(String(c))),
      contains: (c) => s.has(String(c)),
    };
  }
  get className() { return [...this._cls].join(" "); }
  set className(v) {
    this._cls.clear();
    for (const c of String(v).split(/\s+/)) if (c) this._cls.add(c);
  }
  get dataset() { return this._dataset; }
  setAttribute(name, value) {
    if (name.startsWith("data-")) this._dataset[name.slice(5)] = String(value);
    else this._props[name] = String(value);
  }
  getAttribute(name) { return this._props[name]; }
  focus() {}
  addEventListener(type, fn) { (this._listeners[type] || []).push(fn); }
  dispatch(type) {
    return (this._listeners[type] || []).map((fn) => fn({ target: this }));
  }
  get textContent() { return this._text + this._descendants().map((c) => c.textContent).join(""); }
  set textContent(v) { this._text = String(v); this._children.length = 0; }
  set innerHTML(v) { this._text = String(v); this._children.length = 0; }
  appendChild(c) {
    if (c._parent) c._parent._children.splice(c._parent._children.indexOf(c), 1);
    c._parent = this;
    this._children.push(c);
    return c;
  }
  insertBefore(c, ref) {
    if (c._parent) c._parent._children.splice(c._parent._children.indexOf(c), 1);
    const i = this._children.indexOf(ref);
    if (i >= 0) this._children.splice(i, 0, c); else this._children.push(c);
    c._parent = this;
    return c;
  }
  removeChild(c) {
    const i = this._children.indexOf(c);
    if (i >= 0) { this._children.splice(i, 1); c._parent = null; }
    return c;
  }
  _descendants() {
    const out = [];
    for (const c of this._children) { out.push(c); out.push(...c._descendants()); }
    return out;
  }
  querySelector(sel) {
    return this._descendants().find((n) => matchSel(n, sel)) || null;
  }
  querySelectorAll(sel) {
    return this._descendants().filter((n) => matchSel(n, sel));
  }
  closest(sel) {
    let e = this;
    while (e) { if (matchSel(e, sel)) return e; e = e._parent; }
    return null;
  }
}

class FakeDocument {
  constructor() {
    this._listeners = {};
    this._byId = new Map();
    this.documentElement = new Element("html");
    this.documentElement._id = "html";
  }
  addEl(id) {
    const e = new Element("div");
    if (id != null) e._id = String(id);
    this._byId.set(id, e);
    return e;
  }
  getElementById(id) { return this._byId.get(id) || null; }
  createElement(tag) { const e = new Element(tag); _registry.add(e); return e; }
  addEventListener(type, fn) { (this._listeners[type] || []).push(fn); }
  dispatch(type, data) {
    return (this._listeners[type] || []).map((fn) => fn(data));
  }
  querySelector(sel) {
    return [..._registry].find((n) => matchSel(n, sel)) || null;
  }
  querySelectorAll(sel) {
    return [..._registry].filter((n) => matchSel(n, sel));
  }
}

module.exports = { Element, FakeDocument };
