    window.__mCount = (window.__mCount || 0) + 1;
    const el = document.elementFromPoint(ev.clientX, ev.clientY);
    window.__mLast = { y: Math.round(ev.clientY), el: el ? (el.id || el.tagName + "." + el.className.replace(/\s+/g, ".") ) : "null" };
    if (window.__mCount === 1 || window.__mCount % 5 === 0) console.log("ONMOVE #" + window.__mCount + " " + JSON.stringify(window.__mLast));
