/* ==========================================================================
   Перетаскивание (pointer events; мышь — за весь блок,
   сенсорные экраны — за «ручку» из трёх точек)
   ========================================================================== */
const isCoarse = matchMedia("(pointer: coarse)").matches;

function bindDnD() {
  for (const item of panesEl.querySelectorAll(".disc-item")) {
    const anchor = isCoarse ? item.querySelector(".disc-handle") : item;
    anchor.addEventListener("pointerdown", (e) => startDrag(e, item));
  }
}

function startDrag(e, item) {
  if (!e.isPrimary) return;
  if (isCoarse) { e.preventDefault(); e.stopPropagation(); }
  const anchor = e.currentTarget;
  const anchorId = e.pointerId;

  item.classList.add("is-dragging");
  let onMove, onUp;

  onMove = (ev) => {
    if (ev.pointerId !== anchorId) return;
    window.__mCount = (window.__mCount || 0) + 1;
    const el = document.elementFromPoint(ev.clientX, ev.clientY);
    window.__mLast = { y: Math.round(ev.clientY), el: el ? (el.id || el.tagName + "." + el.className.replace(/\s+/g, ".") ) : "null" };
    if (window.__mCount === 1 || window.__mCount % 5 === 0) console.log("ONMOVE #" + window.__mCount + " " + JSON.stringify(window.__mLast));
    if (!el) return;
    const target = el.closest(".disc-item");
    if (!target || target === item) return;
    const list = item.closest(".disc-list");
    if (!list || list !== target.closest(".disc-list")) return;
    list.querySelectorAll(".disc-item.is-over").forEach((x) => {
      if (x !== item) x.classList.remove("is-over");
    });
    const rect = target.getBoundingClientRect();
    const before = ev.clientY < rect.top + rect.height / 2;
    list.insertBefore(item, before ? target : target.nextSibling);
    if (target !== item) target.classList.add("is-over");
  };

  onUp = () => {
    anchor.removeEventListener("pointermove", onMove);
    anchor.removeEventListener("pointerup", onUp);
    anchor.removeEventListener("pointercancel", onUp);
    item.classList.remove("is-dragging");
    item.closest(".disc-list").querySelectorAll(".disc-item.is-over").forEach((x) => {
      if (x !== item) x.classList.remove("is-over");
    });
  };

  try {
    anchor.setPointerCapture(anchorId);
  } catch (_) { /* не критично */ }
  anchor.addEventListener("pointermove", onMove);
  anchor.addEventListener("pointerup", onUp);
  anchor.addEventListener("pointercancel", onUp);
}

